entries.signature:
loop<infer State>(
	startingWith state: State,
	while condition: (_: State) -> Boolean,
	_ advance: (_: State) -> State,
) -> State

examples:
constant doubled = loop(
	startingWith 1,
	while (n) { <- n::isLessThan(100) },
	(n) { <- n::multiply(with 2) },
)

expect doubled::is(128)

constant unchanged = loop(
	startingWith 500,
	while (n) { <- n::isLessThan(100) },
	(n) { <- n::multiply(with 2) },
)

expect unchanged::is(500)

entries.signature:
loop<infer State>(
	from start: Integer,
	through end: Integer,
	startingWith state: State,
	_ advance: (_: Integer, _: State) -> State,
) -> State

examples:
constant total = loop(from 1, through 10, startingWith 0, (index, sum) {
	<- sum::add(index)
})

expect total::is(55)

constant backwards = loop(from 3, through 1, startingWith "none", (index, text) {
	<- "{text}{index}"
})

expect backwards::is("none")

