entries.signature:
loop<infer State>(
	from start: Integer,
	downTo end: Integer,
	startingWith state: State,
	_ advance: (_: Integer, _: State) -> State,
) -> State

examples:
constant countdown = loop(from 3, downTo 1, startingWith "", (index, text) {
	<- "{text}{index}"
})

expect countdown::is("321")

constant once = loop(from 1, downTo 3, startingWith "", (index, text) {
	<- "{text}{index}"
})

expect once::is("1")

constant answer = loop(startingWith 1, step (n) {
	if n::isGreaterThan(50) {
		<- #Done("the first power of two over 50 is {n}")
	}

	<- #Continue(n::multiply(with 2))
})

expect answer::is("the first power of two over 50 is 64")

entries.signature:
loop<infer State>(
	from start: Integer,
	through end: Integer,
	startingWith state: State,
	step advance: (_: Integer, _: State) -> Step<State, State>,
) -> State

examples:
constant firstOverTen = loop(
	from 1,
	through 100,
	startingWith 0,
	step (index, total) {
		constant next = total::add(index)

		if next::isGreaterThan(10) {
			<- #Done(next)
		}

		<- #Continue(next)
	},
)

expect firstOverTen::is(15)

entries.signature:
loop<infer State>(
	from start: Integer,
	upTo end: Integer,
	startingWith state: State,
	step advance: (_: Integer, _: State) -> Step<State, State>,
) -> State

examples:
constant firstBigSquare = loop(
	from 0,
	upTo 10,
	startingWith 0,
	step (index, found) {
		if index::multiply(with index)::isGreaterThan(20) {
			<- #Done(index)
		}

		<- #Continue(found)
	},
)

expect firstBigSquare::is(5)

entries.signature:
loop<infer State>(
	from start: Integer,
	downTo end: Integer,
	startingWith state: State,
	step advance: (_: Integer, _: State) -> Step<State, State>,
) -> State

examples:
constant stopped = loop(
	from 5,
	downTo 1,
	startingWith "",
	step (index, text) {
		if index::is(2) {
			<- #Done("{text}stop")
		}

		<- #Continue("{text}{index} ")
	},
)

expect stopped::is("5 4 3 stop")

modes.declaration:
choice Step<State, Answer> {
	Continue { state: State },
	Done { value: Answer },
}
